  // Dirty worktree
  const m3 = createManifest({ dirtyWorktree: true });
  const comp3 = CeriBaselineComparator.checkComparability(m3, sampleBaseline);
  assert.equal(comp3.eligible, false);
  assert.match(comp3.reasons[0], /dirty worktree/i);
